import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Squared-fill best fit with a near-perfect-fit bonus."""
    cap = float(np.max(bins))  # an empty bin has full capacity
    if cap <= 0:
        return np.zeros_like(bins, dtype=float)
    leftover = bins - item                 # space left after placing item
    fill = 1.0 - leftover / cap            # fill fraction after placing item
    score = fill ** 2                      # strongly prefer fuller bins
    score = score + 0.5 * (leftover <= 0.01 * cap)  # bonus for near-perfect fit
    return score.astype(float)
